import { HardCopySectionStyle } from './index.style'
import { Row } from '../../commonStyle/index.style'
import CustomText from '../CustomText'
import VerticalRadioGroup from '../VerticalRadioGroup'
import CustomCheckbox from '../CustomCheckbox'
import { LANG_STRINGS } from '../../lang'
import { AgentColorPallette } from '../../configs/colorPallete'
import { useCallback, useMemo, useRef, useState, Fragment, useEffect } from 'react'
import { formatMoney } from '../../helpers/utility'
import TitleError from '../TitleError'
import { getRecipientInfoForm, HARD_COPY_OPTION, REQUIRED_ADDRESS_FIELD, SEND_TO_AGENT, SEND_TO_ANOTHER, SEND_TO_CUSTOMER, SEND_TO_PASARPOLIS } from '../../constants/hardCopy'
import { useGlobalContextValue } from '../../contextProvider/GlobalContext'
import { PASARPOLIS_ADDRESS } from '../../constants/appConstants'
import AddressForm from '../AddressForm'
import Button from '../Button'
import InnerInput from '../InnerInput'
import NumericInput from '../NumericInput'
import AgentAddressModal from '../AgentAddress/AddressModal'
import isEmpty from 'lodash/isEmpty'

function HardCopySection ({
  isCustomerForm, isHardCopyRequired, proposedAdminFee = 0, preFilledData = {}, isHideSendToPP = false, onChange = () => {}
}) {
  const [hardCopyRequired, setHardCopyRequired] = useState(!!preFilledData.hard_copy_required || isHardCopyRequired)
  const [selectedHardCopyType, setSelectedHardCopyType] = useState(preFilledData.hard_copy_sent_to || '')
  const [
    {
      customerData = {
        customer_address: (preFilledData.customer_address || {}),
        customer_name: preFilledData.customer_name,
        mobile_no: preFilledData.mobile_no
      },
      getAgentDetailData = {},
      isStaffAgent
    }
  ] = useGlobalContextValue()
  const [errorMap, setErrorMap] = useState({})
  const [showAgentAddressModal, setShowAgentAddressModal] = useState(false)
  const hardCopyAddressRef = useRef(
    {
      hard_copy_address: preFilledData.hard_copy_address,
      hard_copy_required: hardCopyRequired,
      hard_copy_sent_to: preFilledData.hard_copy_sent_to,
      hard_copy_recipient: preFilledData.hard_copy_recipient,
      hard_copy_recipient_mobile: preFilledData.hard_copy_recipient_mobile
    }
  )
  const hardCopyRecipientRef = useRef({
    hard_copy_recipient: hardCopyAddressRef.current.hard_copy_recipient,
    hard_copy_recipient_mobile: hardCopyAddressRef.current.hard_copy_recipient_mobile
  })
  const hardCopyAnotherRef = useRef({})
  const hardAgentAddressRef = useRef({})

  const hardCopyOptions = useMemo(() => {
    const hardCopyOpt = [...HARD_COPY_OPTION]
    const agentAddress = getAgentDetailData?.address

    if ((isStaffAgent && isEmpty(agentAddress)) || isCustomerForm) {
      // if its a customer form or staff login
      // then remove the send_to_agent option
      hardCopyOpt.splice(1, 1)
    }
    if (isHideSendToPP) {
      hardCopyOpt.splice(-1, 1)
    }
    return hardCopyOpt
  }, [isStaffAgent, isCustomerForm,
    isHideSendToPP, getAgentDetailData
  ])

  const isHardCopyError = useMemo(() => {
    return (hardCopyRequired || isHardCopyRequired) && errorMap.hard_copy_recipient
  }, [hardCopyRequired, errorMap, isHardCopyRequired])

  const saveHardCopyToLocalRef = useCallback((payload) => {
    hardCopyAddressRef.current = {
      ...hardCopyAddressRef.current,
      ...payload
    }
    onChange(hardCopyAddressRef.current)
  }, [onChange])

  const handleHardCopyRequired = useCallback(() => {
    const checked = !hardCopyRequired
    setHardCopyRequired(checked)
    if (!checked) {
      setSelectedHardCopyType('')
      setErrorMap({})
      hardCopyAddressRef.current = {
        hard_copy_address: {},
        hard_copy_required: false,
        hard_copy_sent_to: '',
        hard_copy_recipient: '',
        hard_copy_recipient_mobile: ''
      }
      hardCopyRecipientRef.current = {
        hard_copy_recipient: '',
        hard_copy_recipient_mobile: ''
      }
      hardCopyAnotherRef.current = {}
      hardAgentAddressRef.current = {}
    }
    saveHardCopyToLocalRef({
      hard_copy_required: checked
    })
  }, [saveHardCopyToLocalRef, hardCopyRequired])

  const getRecipientMap = useCallback((name, mobile, address) => {
    return {
      hard_copy_recipient: name,
      hard_copy_address: address,
      hard_copy_recipient_mobile: mobile
    }
  }, [])

  useEffect(() => {
    if (selectedHardCopyType === SEND_TO_CUSTOMER) {
      saveHardCopyToLocalRef({
        hard_copy_address: customerData.customer_address
      })
    }
  }, [customerData?.customer_address, selectedHardCopyType,
    saveHardCopyToLocalRef
  ])

  useEffect(() => {
    setHardCopyRequired(!!preFilledData.hard_copy_required || isHardCopyRequired)
    setSelectedHardCopyType(preFilledData.hard_copy_sent_to || '')
    hardCopyAddressRef.current = {
      hard_copy_address: preFilledData.hard_copy_address,
      hard_copy_required: !!preFilledData.hard_copy_required || isHardCopyRequired,
      hard_copy_sent_to: preFilledData.hard_copy_sent_to,
      hard_copy_recipient: preFilledData.hard_copy_recipient,
      hard_copy_recipient_mobile: preFilledData.hard_copy_recipient_mobile
    }
    hardCopyRecipientRef.current = {
      hard_copy_recipient: preFilledData.hard_copy_recipient,
      hard_copy_recipient_mobile: preFilledData.hard_copy_recipient_mobile
    }
  }, [preFilledData, isHardCopyRequired])

  const getRecipientInfo = useCallback((id) => {
    // if this node get re-render and the id are same then only returns the previous details
    // return {
    //   hard_copy_recipient: hardCopyAddressRef.current.hard_copy_recipient || name,
    //   hard_copy_address: hardCopyAddressRef.current.hard_copy_address || address,
    //   hard_copy_recipient_mobile: hardCopyAddressRef.current.hard_copy_recipient_mobile || mobile
    // }
    if (selectedHardCopyType === id) {
      return getRecipientMap(
        hardCopyAddressRef.current.hard_copy_recipient,
        hardCopyAddressRef.current.hard_copy_recipient_mobile,
        hardCopyAddressRef.current.hard_copy_address
      )
    }
    switch (id) {
      case SEND_TO_CUSTOMER:
        return getRecipientMap(
          customerData.customer_name,
          customerData.mobile_no,
          customerData.customer_address
        )
      case SEND_TO_AGENT:
      {
        return getRecipientMap(
          isStaffAgent ? getAgentDetailData?.parent_name : getAgentDetailData?.name,
          isStaffAgent ? getAgentDetailData?.parent_phone_no : getAgentDetailData?.phone_no,
          getAgentDetailData.address
        )
      }
      default:
        return {
          hard_copy_recipient: '',
          hard_copy_recipient_mobile: ''
        }
    }
  }, [getAgentDetailData, customerData, selectedHardCopyType,
    getRecipientMap, isStaffAgent
  ])

  const handleHardCopyOption = useCallback((option) => {
    // get the hard copy recipient default details on basis of send to
    hardCopyRecipientRef.current = getRecipientInfo(option.id)
    setSelectedHardCopyType(option.id)
    setErrorMap({})
    let anotherAddress = {}
    if (option.id === SEND_TO_ANOTHER) {
      anotherAddress = {
        ...hardCopyAnotherRef.current
      }
    } else if (option.id === SEND_TO_PASARPOLIS) {
      anotherAddress = {
        hard_copy_address: PASARPOLIS_ADDRESS,
        hard_copy_recipient: '',
        hard_copy_recipient_mobile: '',
        is_hard_copy_recipient: false
      }
    }
    saveHardCopyToLocalRef({
      ...anotherAddress,
      ...hardCopyRecipientRef.current,
      hard_copy_sent_to: option.id,
      hard_copy_sent_to_name: option.name
    })
  }, [saveHardCopyToLocalRef, getRecipientInfo])

  const handleGetAddressSubmit = useCallback((type, onSubmit, address) => {
    hardCopyAnotherRef.current.onAnotherAddressSubmit = onSubmit
    hardCopyAnotherRef.current.getAnotherAddress = address
    saveHardCopyToLocalRef({
      ...hardCopyAnotherRef.current
    })
  }, [saveHardCopyToLocalRef])

  const handleChangeInput = useCallback((e, name) => {
    // handle to store recipient info local first
    hardCopyRecipientRef.current = {
      ...hardCopyRecipientRef.current,
      [name]: e?.target ? e.target.value : e
    }
  }, [])

  const handleOnBlur = useCallback(() => {
    saveHardCopyToLocalRef({
      ...hardCopyRecipientRef.current
    })
  }, [saveHardCopyToLocalRef])

  const handleFillAddress = useCallback(() => {
    setShowAgentAddressModal(true)
  }, [])

  HardCopySection.getHardCopyData = useCallback(async (e) => {
    // here we are returning the final data to the parent
    // and create the instance method of the HardCopySection
    // so that with ref or parent component can access those details
    const body = {
      ...hardCopyAddressRef.current
    }
    if (body.hard_copy_required) {
      // validate all fields here
      let isValid = !!body.hard_copy_sent_to
      const error = {}
      if (!isValid) {
        error.hard_copy_sent_to = true
      }
      if (body.hard_copy_sent_to !== SEND_TO_PASARPOLIS) {
        let hardCopyAddress = body.hard_copy_address || {}
        if (body.hard_copy_sent_to === SEND_TO_ANOTHER) {
          hardCopyAddress = await body.onAnotherAddressSubmit(e)
          body.hard_copy_address = hardCopyAddress
        }
        // const addressData = {}
        // here we need to verify other details like postal code, province, city data
        REQUIRED_ADDRESS_FIELD.forEach(field => {
          if (!hardCopyAddress || !hardCopyAddress[field]) {
            isValid = false
            error[field] = true
          }
        })
        if (!body.hard_copy_recipient || !body.hard_copy_recipient_mobile) {
          isValid = false
          error.hard_copy_recipient = !body.hard_copy_recipient
          error.hard_copy_recipient_mobile = !body.hard_copy_recipient_mobile
        }
      }
      if (!isValid && Object.keys(error).length) {
        setErrorMap(error)
      }
      return {
        ...body,
        isValid
      }
    }
    return {}
  }, [])

  const handleAgentAddressSave = useCallback((address) => {
    hardAgentAddressRef.current = address
    setShowAgentAddressModal(false)
  }, [])

  const handleCloseAgentAddressModal = useCallback(() => {
    setShowAgentAddressModal(false)
  }, [])

  const renderInputElement = useCallback(({
    type, index, name, label, defaultValue, required, placeholder, disabled
  }) => {
    let children = null
    if (type === 'name') {
      children = (
        <InnerInput
          placeholder={placeholder}
          name={name}
          defaultValue={defaultValue}
          errorField={errorMap[name] ? name : ''}
          onChange={e => handleChangeInput(e, name)}
          onBlur={e => handleOnBlur(name)}
          disabled={disabled}
          displayBorder
        />
      )
    } else {
      children = (
        <NumericInput
          errorField={errorMap[name] ? name : ''}
          type='phone_number'
          name={name}
          className={`number-box-shadow ${disabled ? 'disabled' : ''}`}
          displayBorder
          defaultValue={defaultValue}
          onChange={(value) => handleChangeInput(value, name)}
          onBlur={() => handleOnBlur(name)}
          placeholder={placeholder}
          disabled={disabled}
        />
      )
    }
    return (
      <Fragment key={name}>
        <TitleError
          title={label}
          required={required}
          error={errorMap[name] && LANG_STRINGS.required}
        />
        {children}
      </Fragment>
    )
  }, [handleChangeInput, handleOnBlur, errorMap])

  const renderRecipientForm = useCallback((recipientName = '', recipientMobile = '', isDisabledFields = false) => {
    const mapData = {
      hard_copy_recipient: hardCopyRecipientRef.current.hard_copy_recipient || recipientName,
      hard_copy_recipient_mobile: hardCopyRecipientRef.current.hard_copy_recipient_mobile || recipientMobile
    }
    const recipientForm = getRecipientInfoForm(mapData, isDisabledFields)
    return (
      recipientForm.map((form) => {
        return renderInputElement(form)
      }, [])
    )
  }, [renderInputElement])

  const renderCustomerAddress = useCallback(() => {
    let addressArr = []
    const customerAddress = customerData?.customer_address
    if (customerAddress?.address && customerAddress.city_name && customerAddress.province_name) {
      addressArr = [
        customerAddress.address,
        `${customerAddress.city_name} ${customerAddress.postal_code}`,
        customerAddress.province_name
      ]
    }
    return (
      <div className='hard-copy-address'>
        {
          renderRecipientForm(customerData.customer_name, customerData.mobile_no)
        }
        <CustomText
          size='10px'
          weight={700}
          color={AgentColorPallette.regular}
        >
          {LANG_STRINGS.address1}
        </CustomText>
        {
          addressArr.length ? (
            <CustomText
              size='13px'
              color={AgentColorPallette.regular}
              className='word-break-address'
            >
              {addressArr.join(', ')}
            </CustomText>
          ) : (
            <CustomText color={AgentColorPallette.errorText}>
              {LANG_STRINGS.pleaseEnterCustomerAddressFromTheAbove}
            </CustomText>
          )
        }
      </div>
    )
  }, [customerData, renderRecipientForm])

  const renderAgentAddress = useCallback(() => {
    const agentAddress = getAgentDetailData.address
    if (!Object.keys(agentAddress).length) {
      return (
        <CustomText
          size='13px'
          color={AgentColorPallette.regular}
          className='hard-copy-address'
          weight={600}
        >
          {LANG_STRINGS.addressDataNotComplete}.
          <CustomText
            size='13px'
            color={AgentColorPallette.goldDarker}
            weight={700}
            onClick={handleFillAddress}
          >
            {LANG_STRINGS.fillYourAddress}.
          </CustomText>
        </CustomText>
      )
    }

    const agentAddressMap = [
      agentAddress.address,
      `${agentAddress.city_name} ${agentAddress.postal_code}`,
      agentAddress.province_name
    ]
    return (
      <div className='hard-copy-address'>
        {
          renderRecipientForm(
            isStaffAgent ? getAgentDetailData?.parent_name : getAgentDetailData?.name,
            isStaffAgent ? getAgentDetailData?.parent_phone_no : getAgentDetailData?.phone_no,
            isStaffAgent
          )
        }
        <CustomText
          size='10px'
          weight={700}
          color={AgentColorPallette.regular}
          className='word-break-address'
        >
          {LANG_STRINGS.address1}
        </CustomText>
        <CustomText
          size='13px'
          color={AgentColorPallette.regular}
        >
          {agentAddressMap.join(', ')}
        </CustomText>
        {
          !isStaffAgent &&
            <Button
              width='30px'
              className='change-agent-address-btn'
              onClick={handleFillAddress}
            >
              {LANG_STRINGS.changeAddress}
            </Button>
        }
      </div>
    )
  }, [getAgentDetailData, handleFillAddress,
    renderRecipientForm, isStaffAgent
  ])

  const renderAnotherAddress = useCallback(() => {
    return (
      <div className='hard-copy-address'>
        {
          renderRecipientForm()
        }
        <AddressForm
          addressType='hard-copy-address'
          address={preFilledData.hard_copy_sent_to === SEND_TO_ANOTHER ? hardCopyAddressRef.current.hard_copy_address : {}}
          handleGetAddressSubmit={handleGetAddressSubmit}
        />
      </div>
    )
  }, [renderRecipientForm, handleGetAddressSubmit,
    preFilledData
  ])

  const renderOptionChild = useCallback(({ id, name }) => {
    switch (id) {
      case SEND_TO_CUSTOMER:
        return renderCustomerAddress(name)
      case SEND_TO_AGENT:
        return renderAgentAddress(name)
      case SEND_TO_ANOTHER:
        return renderAnotherAddress(name)
      default:
        return (
          <CustomText
            size='13px'
            color={AgentColorPallette.regular}
            className='hard-copy-address'
          >
            {PASARPOLIS_ADDRESS.address}
          </CustomText>
        )
    }
  }, [renderCustomerAddress, renderAnotherAddress, renderAgentAddress])

  const renderHardCopyOption = useCallback(() => {
    return (
      hardCopyOptions.map(option =>
        <VerticalRadioGroup
          key={option.name}
          data={option}
          name={option.name}
          selected={selectedHardCopyType}
          label={
            <CustomText
              size='13px'
              color={AgentColorPallette.regular}
              padLeft='10px'
            >
              {option.name}
            </CustomText>
          }
          onChange={handleHardCopyOption}
          className='hard-copy-option'
          levelRightPosition
        >
          {renderOptionChild(option)}
        </VerticalRadioGroup>
      )
    )
  }, [
    selectedHardCopyType, hardCopyOptions,
    renderOptionChild, handleHardCopyOption
  ])

  return (
    <HardCopySectionStyle>
      {
        <Row justify='space-between'>
          <CustomText
            color={AgentColorPallette.black}
            size='15px'
            weight={800}
          >
            {LANG_STRINGS.printPolicy}
          </CustomText>
          <CustomCheckbox
            color={AgentColorPallette.black}
            disabled={isHardCopyRequired}
            isChecked={isHardCopyRequired || hardCopyRequired}
            onChange={handleHardCopyRequired}
            name='hardCopy'
            id='hardCopy'
          />
        </Row>
      }
      <CustomText color={AgentColorPallette.fontSecondary} top='4px'>
        {LANG_STRINGS.selectThisPolicyIfWantHardCopy}&nbsp;&nbsp;
        {proposedAdminFee > 0 && (
          <span className='additional-hard-copy-cost'>
            {LANG_STRINGS.additionalFeesOnSelectHardCopy.replace('XXXX', formatMoney(proposedAdminFee, 0, ''))}
          </span>
        )}
      </CustomText>
      {
        hardCopyRequired && (
          <>
            <TitleError
              title={LANG_STRINGS.policyDeliveryAddress}
              error={isHardCopyError && LANG_STRINGS.required}
              required
            />
            {
              renderHardCopyOption()
            }
          </>
        )
      }
      {
        showAgentAddressModal && (
          <AgentAddressModal
            show={showAgentAddressModal}
            onClose={handleCloseAgentAddressModal}
            onAgentAddressSave={handleAgentAddressSave}
          />
        )
      }
    </HardCopySectionStyle>
  )
}

export default HardCopySection
