import AgentAddress from '..'
import { useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { LANG_STRINGS } from '../../../lang'
import CircularLoader from '../../CircularLoader'
import FullPageModal from '../../FullPageModal'

function AgentAddressModal ({ onClose, show, onAgentAddressSave = () => {} }) {
  const [{ UPDATE_AGENT_ADDRESS_LOADER }] = useLoaderContextValue()
  return (
    <FullPageModal
      onCloseModal={onClose}
      showModal={show}
      header={LANG_STRINGS.shippingAddress}
      hideCloseIcon
    >
      <CircularLoader
        isLoading={UPDATE_AGENT_ADDRESS_LOADER}
        className='page-loader-height'
      >
        <AgentAddress padTop='16px' onAddressSave={onAgentAddressSave} />
      </CircularLoader>
    </FullPageModal>
  )
}

export default AgentAddressModal
