import { resetError, updateLoader, useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { useCallback, useEffect, useRef } from 'react'
import { DisplayFlexRCC } from '../../../commonStyle/index.style'
import { CustomText } from '../..'
import AddressForm from '../../AddressForm'
import ButtonWithIcon from '../../ButtonWithIcon'
import ShowSnackbar from '../../ShowNotification'
import { AgentColorPallette } from '../../../configs/colorPallete'
import { useGlobalContextValue } from '../../../contextProvider/GlobalContext'
import { SEND_GOLD_ICON } from '../../../images'
import { LANG_STRINGS } from '../../../lang'
import { useGetAgentDetails } from '../../../state/globalState/hooks/useGlobalContext'
import { useUpdateAgentAddress } from '../state/hooks/useAgentAddress'
import { AgentAddressStyle } from './index.style'

function AgentAddressContainer (props) {
  const agentAddressSubmitRef = useRef('')
  const [, getAgentDetailsRequest] = useGetAgentDetails()
  const [, updateAgentAddressRequest] = useUpdateAgentAddress()
  const [{ UPDATE_AGENT_ADDRESS_ERROR, updateAgentAddressStatus }, dispatchError] = useErrorContextValue()
  const [, dispatchLoader] = useLoaderContextValue()

  const [{
    getAgentDetailData
  }] = useGlobalContextValue()

  useEffect(() => {
    if (UPDATE_AGENT_ADDRESS_ERROR && updateAgentAddressStatus) {
      ShowSnackbar.error({
        visible: true,
        text: updateAgentAddressStatus
      })
      dispatchError(resetError({
        updateAgentAddressStatus: ''
      }))
    }
    if (updateAgentAddressStatus === 'success') {
      getAgentDetailsRequest()
      ShowSnackbar.success({
        visible: true,
        text: LANG_STRINGS.addressUpdatedSuccessfully
      })
      setTimeout(() => {
        props.onAddressSave()
      }, 1000)
      dispatchError(resetError({
        updateAgentAddressStatus: ''
      }))
    }
  }, [UPDATE_AGENT_ADDRESS_ERROR, updateAgentAddressStatus,
    dispatchError, props, getAgentDetailsRequest
  ])

  useEffect(() => {
    return () => {
      dispatchLoader(updateLoader({
        UPDATE_AGENT_ADDRESS_LOADER: undefined
      }))
    }
  }, [dispatchLoader])

  const handleGetAddressSubmit = useCallback((addressType, submitMethod) => {
    agentAddressSubmitRef.current = submitMethod
  }, [])

  const handleSubmit = useCallback(async (e) => {
    const reponseAddrSubmit = await agentAddressSubmitRef.current(e)
    if (reponseAddrSubmit) {
      updateAgentAddressRequest({
        body: reponseAddrSubmit
      })
    }
  }, [agentAddressSubmitRef, updateAgentAddressRequest])

  return (
    <AgentAddressStyle padTop={props.padTop}>
      <div className='content'>
        <CustomText
          color={AgentColorPallette.regular}
          lineHeight={1.5}
          size='13px'
          weight={600}
          bottom='10px'
        >
          {LANG_STRINGS.completeFormBelow}.
        </CustomText>
        <AddressForm
          addressType='agent-address'
          handleGetAddressSubmit={handleGetAddressSubmit}
          address={getAgentDetailData.address ? getAgentDetailData.address : {}}
          labels={{
            province: LANG_STRINGS.province,
            city: LANG_STRINGS.city,
            postalCode: LANG_STRINGS.postalCode,
            address: LANG_STRINGS.completeAddress
          }}
        />
      </div>
      <div className='bottom-action-container'>
        <DisplayFlexRCC className='bottom-continue-btn'>
          <ButtonWithIcon
            id='agent-address-submit'
            className='start-btn'
            text={LANG_STRINGS.save}
            icon={SEND_GOLD_ICON}
            iconRight
            onClick={handleSubmit}
          />
        </DisplayFlexRCC>
      </div>
      <ShowSnackbar hideOkay />
    </AgentAddressStyle>
  )
}

export default AgentAddressContainer
