export const getHardCopyRecipientForm = (data = {}) => {
  return {
    fields: [
      {
        type: 'name',
        label: LANG_STRINGS.recipientName,
        placeholder: LANG_STRINGS.recipientName,
        defaultValue: data?.hard_copy_recipient,
        name: 'hard_copy_recipient'
      },
      {
        type: 'phone_number',
        label: LANG_STRINGS.activeMobileNumber,
        placeholder: 'Nomor Handphone E.g., 08xxxxxxxxx',
        defaultValue: data?.hard_copy_recipient_mobile,
        className: 'customer-phone-input',
        name: 'hard_copy_recipient_mobile'
      }
    ]
  }
}

export const getRecipientInfoForm = (data, isDisabledFields = false) => {
  return ([
    {
      type: 'name',
      label: LANG_STRINGS.recipientName,
      placeholder: LANG_STRINGS.recipientName,
      defaultValue: data?.hard_copy_recipient,
      required: true,
      name: 'hard_copy_recipient',
      disabled: isDisabledFields
    },
    {
      type: 'phone_number',
      label: LANG_STRINGS.activeMobileNumber,
      placeholder: 'Nomor Handphone E.g., 08xxxxxxxxx',
      defaultValue: data?.hard_copy_recipient_mobile,
      className: 'customer-phone-input',
      required: true,
      name: 'hard_copy_recipient_mobile',
      disabled: isDisabledFields
    }
  ])
}

