import { Component } from 'react'
import PropTypes from 'prop-types'
import Modal from '../../../Modal'
import CustomText from '../../../CustomText'
import { AgentColorPallette } from '../../../../configs/colorPallete'

class ImageGuideModal extends Component {
  static propTypes = {
    showImgModal: PropTypes.bool,
    title: PropTypes.string,
    bottomTitle: PropTypes.string,
    imgUrl: PropTypes.string,
    onClose: PropTypes.func
  }

  render () {
    const { title, showImgModal, onClose, modalImgContainer, bottomTitle } = this.props
    return (
      <Modal
        heading={title}
        isOpen={showImgModal}
        onClose={onClose}
      >
        {
          modalImgContainer
        }
        <CustomText color={AgentColorPallette.black} top='20px'>
          {bottomTitle}
        </CustomText>
      </Modal>
    )
  }
}

export default ImageGuideModal
